const item = $input.first().json;
const content = item.output || item.text || '';
const wordCount = content.trim().split(/\s+/).filter(Boolean).length;
return [{ json: { generated_content: content, word_count: wordCount, original_request: $('When chat message received').first().json.chatInput } }];

const item = $input.first().json;
const reviewRaw = (item.output || item.text || '').toString();

function parseField(text, label) {
  const regex = new RegExp(label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*:\\s*(.+)', 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : '';
}

const check1 = parseField(reviewRaw, 'Check 1 - No PII');
const check2 = parseField(reviewRaw, 'Check 2 - Professional Tone');
const check3 = parseField(reviewRaw, 'Check 3 - Length Limit');
const check4 = parseField(reviewRaw, 'Check 4 - No Unsubstantiated Claims');
const overallRaw = parseField(reviewRaw, 'Overall Result');
const summary = parseField(reviewRaw, 'Summary');

const overallResult = overallRaw.toUpperCase().includes('PASS') ? 'PASS' : 'FAIL';

const prep = $('Prepare for Review').first().json;

return [{
  json: {
    generated_content: prep.generated_content,
    word_count: prep.word_count,
    check_no_pii: check1,
    check_professional_tone: check2,
    check_length_limit: check3,
    check_unsubstantiated_claims: check4,
    overall_result: overallResult,
    summary: summary,
    reviewed_at: new Date().toISOString()
  }
}];
